    ents.append('    {slug:%s,title:%s,category:%s,excerpt:%s,author:"GamblingLawyers.com Editorial Team",author_slug:"",publish_date:%s,related_jurisdictions:%s,related_firms:%s,related_lawyers:[]}'%(q(a["slug"]),q(a["title"]),q(a["category"]),q(a["excerpt"]),q(a["time"]),q(a["juris"]),q(a["firms"])))
